bool claim(std::optional<MatchRecord> record) {
  if (stage_ != Stage::open) return false;
  if (!record) {
    stage_ = Stage::not_eligible;
    return true;
  }
  if (record->key != key_) {
    throw std::invalid_argument("ResultHandoff claim key mismatch");
  }
  request_ = std::move(record);
  stage_ = Stage::inflight;
  return true;
}

bool complete(uint64_t key, const Reply& reply) {
  if (stage_ != Stage::inflight || key != key_) return false;

  bool confirmed = false;
  if (reply.kind == Reply::confirmed && request_.has_value()) {
    const Receipt& r = reply.receipt;
    confirmed = r.key == key_ && r.row > 0 &&
                r.player_a == request_->player_a &&
                r.player_b == request_->player_b;
  }
  stage_ = confirmed ? Stage::confirmed : Stage::unconfirmed;
  return true;
}

template<class Clock>
PacedReply receive(std::uint64_t actor,const Frame& frame,Clock&& clock) {
    std::lock_guard<std::mutex> lock(mutex_);
    // Sample the trusted clock AFTER serialization, not in waiting readers.
    return channel_.receive(actor,frame,clock());
}

template<class Sender>
bool finalize(Sender&& sender) {
    std::optional<MatchRecord> request;
    {
        std::lock_guard<std::mutex> lock(mutex_);
        if(!channel_.claim())return false;
        request=channel_.request();
    }
    if(!request)return true; // Incomplete/invalid/budget-exhausted: no storage.
    Reply reply;
    try { reply=sender(*request); }
    catch(...) { reply=Reply{}; } // Failure to confirm is not rollback proof.
    {
        std::lock_guard<std::mutex> lock(mutex_);
        channel_.complete(request->key,reply);
    }
    return true;
}

